'use strict';

const { shiftAndMerge } = require('./mergeLogic.js');

class Game {
  constructor(initialState = null, settings = {}) {
    this.settings = {
      size: settings.size || 4,
      winValue: settings.winValue || 2048,
    };

    this.size = this.settings.size;
    this.score = 0;
    this.status = 'idle';
    this.hasWon = false;
    this.keepPlaying = false;
    this.history = [];

    this.board = this.isValidBoard(initialState)
      ? this.cloneBoard(initialState)
      : this.createEmptyBoard();

    this.updateStatus();
  }

  // ---------- Helpers ----------
  createEmptyBoard() {
    return Array.from({ length: this.size }, () => Array(this.size).fill(0));
  }

  cloneBoard(board) {
    return board.map((row) => [...row]);
  }

  isValidBoard(board) {
    return (
      Array.isArray(board) &&
      board.length === this.size &&
      board.every(
        (row) =>
          Array.isArray(row) &&
          row.length === this.size &&
          row.every((cell) => Number.isInteger(cell) && cell >= 0),
      )
    );
  }

  boardsEqual(b1, b2) {
    return b1.every((row, r) => row.every((val, c) => val === b2[r][c]));
  }

  // ---------- Public Getters ----------
  getScore() {
    return this.score;
  }

  getState() {
    return this.cloneBoard(this.board);
  }

  getStatus() {
    return this.status;
  }

  getSettings() {
    return { ...this.settings };
  }

  hasUserWon() {
    return this.hasWon;
  }

  // ---------- Game Control ----------
  start(customBoard = null) {
    this.score = 0;
    this.hasWon = false;
    this.keepPlaying = false;
    this.status = 'playing';
    this.history = [];

    if (this.isValidBoard(customBoard)) {
      this.board = this.cloneBoard(customBoard);
    } else {
      this.board = this.createEmptyBoard();
      this.spawnTile();
      this.spawnTile();
    }

    this.updateStatus();
  }

  restart(customBoard = null) {
    this.start(customBoard);
  }

  setBoard(board) {
    if (this.isValidBoard(board)) {
      this.board = this.cloneBoard(board);
      this.updateStatus();
    }
  }

  // ---------- Moves ----------
  saveHistory() {
    this.history.push({
      board: this.cloneBoard(this.board),
      score: this.score,
      status: this.status,
      hasWon: this.hasWon,
      keepPlaying: this.keepPlaying,
    });

    if (this.history.length > 20) {
      this.history.shift();
    }
  }

  undo() {
    if (this.history.length === 0) {
      return;
    }

    const last = this.history.pop();

    this.board = this.cloneBoard(last.board);
    this.score = last.score;
    this.status = last.status;
    this.hasWon = last.hasWon;
    this.keepPlaying = last.keepPlaying;
  }

  moveLeft() {
    this.performMove('left');
  }

  moveRight() {
    this.performMove('right');
  }

  moveUp() {
    this.performMove('up');
  }

  moveDown() {
    this.performMove('down');
  }

  performMove(direction) {
    if (this.status !== 'playing') {
      return;
    }

    const prevBoard = this.board;
    const { board: newBoard, totalScore } = shiftAndMerge(prevBoard, direction);

    if (!this.boardsEqual(prevBoard, newBoard)) {
      this.saveHistory();
      this.board = newBoard;
      this.score += totalScore;

      if (
        !this.hasWon &&
        this.board.flat().some((val) => val >= this.settings.winValue)
      ) {
        this.hasWon = true;

        if (!this.keepPlaying) {
          this.status = 'win';
        }
      }

      if (this.status === 'playing') {
        this.spawnTile();
        this.updateStatus();
      }
    }
  }

  // ---------- Logic ----------
  canMove() {
    return ['up', 'down', 'left', 'right'].some((dir) => {
      const { board: moved } = shiftAndMerge(this.board, dir);

      return !this.boardsEqual(this.board, moved);
    });
  }

  spawnTile(row = null, col = null, value = null) {
    if (this.status !== 'playing') {
      return;
    }

    const emptyCells = [];

    for (let r = 0; r < this.size; r++) {
      for (let c = 0; c < this.size; c++) {
        if (this.board[r][c] === 0) {
          emptyCells.push([r, c]);
        }
      }
    }

    if (emptyCells.length === 0) {
      return;
    }

    const cell =
      row !== null && col !== null
        ? [row, col]
        : emptyCells[Math.floor(Math.random() * emptyCells.length)];

    const [targetRow, targetCol] = cell;

    this.board[targetRow][targetCol] =
      value !== null ? value : Math.random() < 0.9 ? 2 : 4;
  }

  updateStatus() {
    if (this.hasWon && !this.keepPlaying) {
      this.status = 'win';
    } else if (!this.canMove()) {
      this.status = 'lose';
    } else if (this.status === 'idle') {
      this.status = 'playing';
    }
  }

  // ---------- Settings ----------
  setSettings(newSettings = {}) {
    if (Number.isInteger(newSettings.size) && newSettings.size > 1) {
      this.settings.size = newSettings.size;
      this.size = newSettings.size;
    }

    if (Number.isInteger(newSettings.winValue) && newSettings.winValue > 0) {
      this.settings.winValue = newSettings.winValue;
    }

    this.restart();
  }

  // ---------- Keep Playing ----------
  keepGoing() {
    if (this.status === 'win') {
      this.keepPlaying = true;
      this.status = 'playing';
      this.updateStatus();
    }
  }
}

module.exports = Game;
